import React, { useState } from 'react';

const Contact = () => {
  const [form, setForm] = useState({ name: '', phone: '', email: '', choice: '', message: '' });
  const [status, setStatus] = useState('idle');
  const [openFaq, setOpenFaq] = useState(null);

  const faqs = [
    ['How do I join the online classes?', 'Choose your course, complete the enrolment process, and our team will share your class schedule and joining details.'],
    ['Are the classes live or recorded?', 'Our courses include live interactive classes along with learning resources and recordings where applicable.'],
    ['Will I get a certificate after the course?', 'Students who successfully complete the required course work can receive a course completion certificate.'],
    ['Do you provide placement support?', 'We provide placement guidance, interview preparation, resume support and career assistance.'],
    ['What if I miss a live class?', 'You can contact our support team for the available recording or alternate learning arrangement.'],
    ['How can I make the payment?', 'Our team will provide the available payment options and instructions during enrolment.']
  ];

  const handleChange = e => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async e => {
    e.preventDefault();
    setStatus('sending');
    const body = new FormData();
    body.append('access_key', 'a70b7dfc9b3b49499bcfb8c178f936ae');
    body.append('name', form.name);
    body.append('phone', form.phone);
    body.append('email', form.email);
    body.append('choice', form.choice);
    body.append('message', form.message);
    try {
      const response = await fetch('https://splitforms.com/api/submit', { method: 'POST', headers: { Accept: 'application/json' }, body });
      if (!response.ok) throw new Error('Submission failed');
      setForm({ name: '', phone: '', email: '', choice: '', message: '' });
      setStatus('success');
      setTimeout(() => setStatus('idle'), 6000);
    } catch {
      setStatus('error');
    }
  };

  return (
    <>
      <style>{`
        * { box-sizing: border-box; }
        .contact-page { width: 100%; font-family: 'Inter', Arial, sans-serif; color: #e0e0e0; background: #000; overflow: hidden; }
        .contact-page button, .contact-page input, .contact-page select, .contact-page textarea { font-family: inherit; }
        
        /* Hero Section */
        .contact-hero { position: relative; min-height: 470px; background: linear-gradient(90deg, rgba(0,0,0,0.95) 0%, rgba(0,0,0,0.8) 40%, rgba(8,8,59,0.6) 100%), url("https://images.unsplash.com/photo-1551836022-d5d88e9218df?auto=format&fit=crop&w=1800&q=90") center/cover no-repeat; }
        .contact-hero:after { content: ""; position: absolute; inset: 0; background: linear-gradient(90deg, rgba(0,0,0,0.9) 0%, rgba(0,0,0,0.7) 50%, rgba(0,0,0,0.3) 100%); }
        .hero-container { position: relative; z-index: 2; width: min(1180px, calc(100% - 48px)); min-height: 470px; margin: auto; display: flex; align-items: center; }
        .hero-content { width: 60%; padding: 45px 0; }
        .hero-label { font-size: 13px; letter-spacing: 4px; font-weight: 900; color: #00d2ff; margin-bottom: 13px; text-transform: uppercase; }
        .hero-title { font-family: Georgia, "Times New Roman", serif; font-size: 57px; line-height: .98; letter-spacing: -1px; color: #ffffff; margin: 0; }
        .hero-title span { color: #f5c65b; }
        .hero-description { max-width: 570px; color: #cccccc; font-size: 16px; line-height: 1.6; margin: 19px 0 25px; }
        .hero-features { display: grid; grid-template-columns: repeat(3, 1fr); max-width: 540px; }
        .hero-feature { display: flex; align-items: center; gap: 10px; border-right: 1px solid rgba(255,255,255,0.1); padding: 5px 17px 5px 0; margin-right: 17px; }
        .hero-feature:last-child { border: 0; }
        .hero-feature-icon { font-size: 26px; color: #00d2ff; }
        .hero-feature-text { font-size: 13px; line-height: 1.35; color: #eeeeee; font-weight: 700; }
        
        /* Floating Accents */
        .hero-question { position: absolute; z-index: 3; left: 47%; top: 63px; color: #f5c65b; font-family: "Comic Sans MS", cursive; font-size: 21px; line-height: 1.05; font-style: italic; transform: rotate(-7deg); text-align: center; }
        .hero-question:after { content: ""; display: block; width: 78px; height: 3px; background: #00d2ff; margin: 8px auto; transform: rotate(-8deg); border-radius: 2px; }
        .hero-smile { color: #00d2ff; font-size: 27px; }
        .hero-contact-list { position: absolute; z-index: 3; right: 0; top: 25px; width: 195px; }
        .hero-contact-item { height: 48px; margin-bottom: 7px; border-radius: 10px; background: #08083B; border: 1px solid rgba(0, 210, 255, 0.2); display: flex; align-items: center; gap: 11px; padding: 0 12px; color: #ffffff; font-size: 11px; font-weight: 700; box-shadow: 0 5px 16px rgba(0,0,0,0.5); transition: .3s ease; cursor: default; }
        .hero-contact-item:hover { transform: translateX(-6px); box-shadow: 0 8px 22px rgba(0, 210, 255, 0.2); border-color: #00d2ff; }
        .hero-contact-icon { width: 30px; height: 30px; border-radius: 8px; display: flex; align-items: center; justify-content: center; background: rgba(0, 210, 255, 0.1); color: #00d2ff; font-size: 16px; flex-shrink: 0; }
        .hero-note { position: absolute; z-index: 4; right: 0; bottom: 25px; color: #cccccc; font-family: "Comic Sans MS", cursive; font-size: 18px; line-height: 1.05; text-align: center; font-style: italic; transform: rotate(-5deg); }
        .hero-note span { color: #f5c65b; font-size: 27px; }
        
        /* Main Section & Grid */
        .contact-main { padding: 50px 0 0; }
        .container { width: min(1180px, calc(100% - 48px)); margin: auto; }
        .contact-grid { display: grid; grid-template-columns: 1fr 1.15fr; gap: 30px; align-items: start; }
        .left-column { display: flex; flex-direction: column; gap: 20px; }
        .right-column { display: flex; flex-direction: column; gap: 20px; }
        
        /* Cards Common */
        .contact-card, .info-card, .quick-card { background: #0a0a0a; border: 1px solid #1a1a1a; border-radius: 17px; padding: 25px; box-shadow: 0 10px 30px rgba(0,0,0,0.8); transition: transform 0.3s ease, border-color 0.3s ease; }
        .contact-card:hover, .info-card:hover, .quick-card:hover { border-color: #2a2a2a; }
        
        /* Left Column Content */
        .info-heading, .quick-heading, .card-heading { display: flex; align-items: center; gap: 15px; margin-bottom: 20px; }
        .info-heading-icon, .quick-icon, .card-heading-icon { width: 52px; height: 52px; border-radius: 15px; background: #08083B; color: #00d2ff; display: flex; align-items: center; justify-content: center; font-size: 24px; border: 1px solid rgba(0, 210, 255, 0.2); }
        .card-title, .quick-title { font-family: Georgia, "Times New Roman", serif; font-size: 26px; color: #ffffff; margin: 0; }
        .card-subtitle, .quick-subtitle { color: #aaaaaa; font-size: 13px; margin: 5px 0 0; line-height: 1.45; }
        
        .info-row { display: flex; align-items: center; gap: 15px; margin: 15px 0; padding: 12px; border-radius: 12px; transition: .3s; background: #111; border: 1px solid transparent; }
        .info-row:hover { background: #000; border-color: #08083B; transform: translateX(5px); box-shadow: 0 6px 18px rgba(0,0,0,0.5); }
        .info-icon { width: 45px; height: 45px; border-radius: 12px; background: #08083B; color: #fff; display: flex; align-items: center; justify-content: center; font-size: 20px; flex-shrink: 0; }
        .info-main { color: #ffffff; font-size: 14px; font-weight: 700; }
        .info-main a { color: #ffffff; text-decoration: none; transition: color 0.2s; }
        .info-main a:hover { color: #00d2ff; }
        .info-detail { color: #888888; font-size: 11px; line-height: 1.5; margin-top: 4px; }
        
        .quick-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
        .quick-item { border: 1px solid #222; background: #111; border-radius: 12px; padding: 14px; display: flex; gap: 12px; align-items: center; transition: .3s; cursor: pointer; }
        .quick-item:hover { border-color: #00d2ff; background: #050505; transform: translateY(-3px); box-shadow: 0 8px 20px rgba(0, 210, 255, 0.1); }
        .quick-item-icon { font-size: 22px; color: #00d2ff; }
        .quick-item-title { font-size: 12px; font-weight: 700; color: #ffffff; }
        .quick-item-text { font-size: 10px; color: #888888; margin-top: 3px; }
        
        /* Contact Form */
        .contact-card { position: relative; overflow: hidden; }
        .contact-card:before { content: ""; position: absolute; top: 0; left: 0; width: 100%; height: 4px; background: #08083B; }
        .form-group { margin-bottom: 15px; position: relative; }
        .input-icon { position: absolute; left: 16px; top: 50%; transform: translateY(-50%); font-size: 16px; color: #00d2ff; z-index: 1; opacity: 0.8; }
        .contact-input, .contact-select, .contact-textarea { width: 100%; border: 1px solid #333; border-radius: 12px; background: #050505; color: #ffffff; font-size: 13px; outline: none; transition: .3s; }
        .contact-input, .contact-select { height: 50px; padding: 0 16px 0 46px; }
        .contact-textarea { height: 130px; padding: 16px 16px 16px 46px; resize: vertical; min-height: 100px; }
        .contact-input:focus, .contact-select:focus, .contact-textarea:focus { border-color: #00d2ff; background: #000; box-shadow: 0 0 0 4px rgba(0, 210, 255, 0.1); transform: translateY(-1px); }
        .contact-select option { background: #0a0a0a; color: #fff; }
        
        /* Button styles requested by user */
        .send-button { width: 100%; height: 52px; border: 2px solid #08083B; border-radius: 30px; background: #08083B; color: #ffffff; font-size: 15px; font-weight: 800; cursor: pointer; margin-top: 10px; transition: all .3s ease; }
        .send-button:hover:not(:disabled) { background: #050505; border-color: #00d2ff; color: #00d2ff; box-shadow: 0 8px 20px rgba(0, 210, 255, 0.2); transform: translateY(-2px); }
        .send-button:disabled { opacity: .65; cursor: not-allowed; transform: none; }
        
        /* Form Messages */
        .success-message, .error-message { margin-top: 15px; padding: 14px; border-radius: 10px; font-size: 13px; text-align: center; font-weight: 700; }
        .success-message { background: rgba(0, 255, 128, 0.1); color: #00ff80; border: 1px solid rgba(0, 255, 128, 0.3); }
        .error-message { background: rgba(255, 50, 50, 0.1); color: #ff5555; border: 1px solid rgba(255, 50, 50, 0.3); }
        .form-trust { display: flex; justify-content: center; gap: 20px; margin-top: 18px; color: #888; font-size: 11px; }
        .form-trust span { display: flex; align-items: center; gap: 6px; }
        
        /* Support Banner */
        .support-banner { position: relative; min-height: 160px; border-radius: 17px; border: 1px solid #1a1a1a; overflow: hidden; margin-top: 30px; background: #050505 url("https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=1400&q=85") center/cover no-repeat; box-shadow: 0 15px 35px rgba(0,0,0,0.6); }
        .support-banner:after { content: ""; position: absolute; inset: 0; background: linear-gradient(90deg, rgba(8,8,59,0.95), rgba(0,0,0,0.85), rgba(0,0,0,0.6)); }
        .support-content { position: relative; z-index: 2; display: flex; align-items: center; min-height: 160px; padding: 25px 30px; color: #fff; }
        .support-icon { width: 60px; height: 60px; border-radius: 16px; background: #00d2ff; color: #000; display: flex; align-items: center; justify-content: center; font-size: 28px; margin-right: 20px; flex-shrink: 0; box-shadow: 0 0 20px rgba(0, 210, 255, 0.4); }
        .support-title { font-family: Georgia, "Times New Roman", serif; font-size: 24px; line-height: 1.1; margin: 0; color: #fff; }
        .support-text { font-size: 12px; margin-top: 8px; max-width: 400px; line-height: 1.6; color: #cccccc; }
        .support-stats { margin-left: auto; display: grid; grid-template-columns: repeat(3, 1fr); background: rgba(0,0,0,0.6); border: 1px solid rgba(255,255,255,0.1); border-radius: 14px; min-width: 400px; backdrop-filter: blur(5px); }
        .support-stat { text-align: center; padding: 15px; border-right: 1px solid rgba(255,255,255,0.1); }
        .support-stat:last-child { border: 0; }
        .support-stat-icon { font-size: 22px; color: #f5c65b; }
        .support-stat-number { font-size: 18px; font-weight: 900; margin-top: 4px; color: #fff; }
        .support-stat-text { font-size: 10px; color: #aaaaaa; margin-top: 2px; text-transform: uppercase; letter-spacing: 1px; }
        
        /* FAQ Section */
        .faq-section { padding: 40px 0 60px; border-top: 1px solid #111; margin-top: 40px; background: #020202; }
        .faq-header { display: flex; align-items: flex-end; justify-content: space-between; margin-bottom: 25px; }
        .faq-label { font-size: 13px; font-weight: 900; letter-spacing: 3px; color: #00d2ff; text-transform: uppercase; }
        .faq-title { font-family: Georgia, "Times New Roman", serif; font-size: 32px; color: #ffffff; margin: 5px 0 0; }
        .faq-title:after { content: ""; display: inline-block; width: 50px; height: 4px; background: #08083B; margin: 0 0 6px 15px; border-radius: 2px; }
        .faq-right { font-size: 13px; color: #aaaaaa; }
        .faq-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 15px 20px; }
        .faq-item { border: 1px solid #1a1a1a; border-radius: 12px; background: #0a0a0a; overflow: hidden; transition: .3s; }
        .faq-item:hover { border-color: #08083B; box-shadow: 0 6px 20px rgba(0,0,0,0.5); }
        .faq-question { width: 100%; min-height: 50px; border: 0; background: transparent; display: flex; justify-content: space-between; align-items: center; text-align: left; padding: 10px 18px; color: #ffffff; font-size: 15px; font-weight: 700; cursor: pointer; transition: color 0.3s; }
        .faq-question:hover { color: #00d2ff; }
        .faq-plus { font-size: 22px; color: #00d2ff; font-weight: 400; transition: transform 0.3s; }
        .faq-answer { padding: 0 18px 18px; color: #aaaaaa; font-size: 14px; line-height: 1.6; border-top: 1px solid #111; margin-top: 5px; padding-top: 15px; }
        
        /* Media Queries */
        @media(max-width: 1000px) {
          .hero-content { width: 63%; }
          .hero-question { left: 49%; }
          .contact-grid { grid-template-columns: 1fr; }
          .support-stats { min-width: 350px; }
        }
        @media(max-width: 700px) {
          .contact-hero { min-height: 620px; background-position: right; }
          .hero-container { width: calc(100% - 30px); min-height: 620px; align-items: flex-start; }
          .hero-content { width: 100%; padding-top: 60px; }
          .hero-title { font-size: 44px; }
          .hero-description { font-size: 15px; }
          .hero-question, .hero-contact-list, .hero-note { display: none; }
          .hero-features { max-width: 100%; grid-template-columns: repeat(3, 1fr); }
          .hero-feature { padding-right: 8px; margin-right: 8px; }
          .container { width: calc(100% - 30px); }
          .contact-grid { gap: 20px; }
          .contact-card, .info-card, .quick-card { padding: 20px; }
          .support-banner { min-height: 320px; }
          .support-content { min-height: 320px; display: block; padding: 25px; }
          .support-icon { margin-bottom: 15px; }
          .support-stats { min-width: 0; width: 100%; margin: 20px 0 0; }
          .faq-header { display: block; }
          .faq-right { margin-top: 10px; }
          .faq-grid { grid-template-columns: 1fr; }
        }
        @media(max-width: 430px) {
          .hero-title { font-size: 38px; }
          .hero-features { grid-template-columns: 1fr; }
          .hero-feature { border-right: 0; border-bottom: 1px solid rgba(255,255,255,0.1); padding: 12px 0; margin: 0; }
          .hero-feature:last-child { border-bottom: 0; }
          .quick-grid { grid-template-columns: 1fr; }
          .support-stats { grid-template-columns: 1fr; }
          .support-stat { border-right: 0; border-bottom: 1px solid rgba(255,255,255,0.1); }
          .support-stat:last-child { border-bottom: 0; }
        }
      `}</style>
      
      <main className="contact-page">
        <section className="contact-hero">
          <div className="hero-container">
            <div className="hero-content">
              <div className="hero-label">CONTACT US</div>
              <h1 className="hero-title">We’re Here<br />to <span>Help You!</span></h1>
              <p className="hero-description">Have questions about our online courses, batches, payments, or certifications? Our team is ready to assist you. Get in touch and take the next step towards your brighter future with Vighnavi Academy.</p>
              <div className="hero-features">
                <div className="hero-feature"><div className="hero-feature-icon">♧</div><div className="hero-feature-text">Quick<br />Response</div></div>
                <div className="hero-feature"><div className="hero-feature-icon">♟</div><div className="hero-feature-text">Friendly<br />Support</div></div>
                <div className="hero-feature"><div className="hero-feature-icon">◷</div><div className="hero-feature-text">Guidance<br />at Every Step</div></div>
              </div>
            </div>
            <div className="hero-question">Your<br />Questions<br />Our Priority<div className="hero-smile">☺</div></div>
            <div className="hero-contact-list">
              {[['🎓', 'Course Guidance'], ['▣', 'Batch Details'], ['◆', 'Fee & Offers'], ['⚙', 'Technical Support'], ['▤', 'Certifications'], ['●', 'General Queries']].map((x, i) => <div className="hero-contact-item" key={i}><div className="hero-contact-icon">{x[0]}</div>{x[1]}</div>)}
            </div>
            <div className="hero-note">We’re<br />Just a Message<br />Away! <span>♡</span></div>
          </div>
        </section>

        <section className="contact-main">
          <div className="container contact-grid">

            <div className="left-column">
              <div className="info-card">
                <div className="info-heading"><div className="info-heading-icon">⌖</div><div><h2 className="card-title">Get in Touch</h2><p className="card-subtitle">Reach out to us through any of the following channels.</p></div></div>
                <div className="info-row"><div className="info-icon">☎</div><div><div className="info-main"><a href="tel:+919390642779">+91 9390642779 / 8688110258</a></div><div className="info-detail">Mon - Sat, 9:00 AM - 7:00 PM<br />Online Support Only</div></div></div>
                <div className="info-row"><div className="info-icon">✉</div><div><div className="info-main"><a href="mailto:vighnaviacademy@gmail.com">vighnaviacademy@gmail.com</a></div><div className="info-detail">We reply within 24 hours</div></div></div>
                <div className="info-row"><div className="info-icon">●</div><div><div className="info-main">Online Classes Only</div><div className="info-detail">Live interactive online training<br />Learn from anywhere, anytime.</div></div></div>
              </div>

              <div className="quick-card">
                <div className="quick-heading"><div className="quick-icon">💡</div><div><h2 className="quick-title">Quick Help Topics</h2><div className="quick-subtitle">Find quick answers or reach the right team faster.</div></div></div>
                <div className="quick-grid">
                  {[['📖', 'Course Information', 'Know about our courses'], ['▣', 'Batch Schedule', 'Upcoming batches'], ['◆', 'Fees & Payment', 'Fee details & offers'], ['▤', 'Certifications', 'Get certified']].map((x, i) => <div className="quick-item" key={i}><div className="quick-item-icon">{x[0]}</div><div><div className="quick-item-title">{x[1]}</div><div className="quick-item-text">{x[2]}</div></div></div>)}
                </div>
              </div>
            </div>

            <div className="right-column">
              <div className="contact-card">
                <div className="card-heading"><div className="card-heading-icon">✉</div><div><h2 className="card-title">Send Us a Message</h2><p className="card-subtitle">Tell us what you are looking for and our team will contact you shortly.</p></div></div>
                <form onSubmit={handleSubmit}>
                  <div className="form-group"><span className="input-icon">♟</span><input className="contact-input" type="text" name="name" value={form.name} onChange={handleChange} placeholder="Full Name *" required /></div>
                  <div className="form-group"><span className="input-icon">☎</span><input className="contact-input" type="tel" name="phone" value={form.phone} onChange={handleChange} placeholder="Phone Number *" pattern="[0-9]{10}" title="Please enter a valid 10 digit phone number" required /></div>
                  <div className="form-group"><span className="input-icon">✉</span><input className="contact-input" type="email" name="email" value={form.email} onChange={handleChange} placeholder="Email Address *" required /></div>
                  <div className="form-group">
                    <span className="input-icon">▤</span>
                    <select className="contact-select" name="choice" value={form.choice} onChange={handleChange} required>
                      <option value="">What are you interested in? *</option>
                      <option>1 : 1 mentorship</option>
                      <option>Python With Sql</option>
                      <option>Java With Sql</option>
                      <option>Java Development</option>
                      <option>Python Development</option>
                      <option>Java Full Stack Development</option>
                      <option>Python Full Stack Development</option>
                      <option>MERN Stack Development</option>
                      <option>Data Analyst</option>
                      <option>Generative AI</option>
                      <option>Course Information</option>
                      <option>Batch Schedule</option>
                      <option>Fees & Payment</option>
                      <option>Certification</option>
                      <option>Technical Support</option>
                      <option>General Query</option>
                    </select>
                  </div>
                  <div className="form-group"><span className="input-icon" style={{ top: '25px' }}>▰</span><textarea className="contact-textarea" name="message" value={form.message} onChange={handleChange} placeholder="Tell us what you want to learn or ask us your question *" required /></div>
                  <button className="send-button" type="submit" disabled={status === 'sending'}>{status === 'sending' ? 'Sending Your Message...' : 'Send Message  →'}</button>
                  {status === 'success' && <div className="success-message">✓ Thank you! Your message has been sent successfully. Our team will contact you shortly.</div>}
                  {status === 'error' && <div className="error-message">⚠ Something went wrong. Please try again or contact us directly.</div>}
                  <div className="form-trust"><span>🔒 Secure Enquiry</span><span>⚡ Quick Response</span><span>✓ Student Support</span></div>
                </form>
              </div>
            </div>
          </div>

          <div className="container">
            <div className="support-banner">
              <div className="support-content">
                <div className="support-icon">♧</div>
                <div><h2 className="support-title">Live Support for<br />Your Learning Journey</h2><p className="support-text">Our support team is always ready to help you with course selection, technical issues, or any other queries.</p></div>
                <div className="support-stats">
                  <div className="support-stat"><div className="support-stat-icon">♟</div><div className="support-stat-number">100%</div><div className="support-stat-text">Student Support</div></div>
                  <div className="support-stat"><div className="support-stat-icon">◷</div><div className="support-stat-number">Quick</div><div className="support-stat-text">Response</div></div>
                  <div className="support-stat"><div className="support-stat-icon">♥</div><div className="support-stat-number">Dedicated</div><div className="support-stat-text">Guidance</div></div>
                </div>
              </div>
            </div>
          </div>
        </section>

        <section className="faq-section">
          <div className="container">
            <div className="faq-header">
              <div><div className="faq-label">FAQ</div><h2 className="faq-title">Common Questions</h2></div>
              <div className="faq-right">Still have a question? Send us a message! →</div>
            </div>
            <div className="faq-grid">
              {faqs.map((faq, i) => (
                <div className="faq-item" key={i}>
                  <button type="button" className="faq-question" onClick={() => setOpenFaq(openFaq === i ? null : i)}>
                    <span>{faq[0]}</span>
                    <span className="faq-plus">{openFaq === i ? '−' : '+'}</span>
                  </button>
                  {openFaq === i && <div className="faq-answer">{faq[1]}</div>}
                </div>
              ))}
            </div>
          </div>
        </section>
      </main>
    </>
  );
};

export default Contact;
